content.content:
  1	/**
  2	 * Incidents on disk and in neatlogs (Node side of src/incidents/derive.ts).
  3	 *
  4	 *   recordRunIncidents   end of a run: derive the run's incidents from runs/<runId>/ (bundle passed in,
  5	 *                        timeline.jsonl, approvals.json, spans.jsonl), write runs/<runId>/incidents.json,
  6	 *                        and send every incident not already reported live to neatlogs as a warn/error
  7	 *                        log() record (plus an info record per resolution), all inside one
  8	 *                        `notary.incidents` EVALUATOR span in the run's trace.
  9	 *   buildIncidentsFile   the IncidentsFile for a bundle + run dir (pure apart from reading files).
 10	 *   publishIncidents     write packages/web/public/incidents/<runId>.json (fixture: .../incidents/fixture/).
 11	 *   writeIncidentsIndex  write <incidentsDir>/index.json: every published run's incidents (one fetch).
 12	 *
 13	 * Never invents anything: an incident exists only when a rule in derive.ts matches recorded data.
 14	 */
 15	import { existsSync, mkdirSync, readFileSync, readdirSync, renameSync, writeFileSync } from "node:fs";
 16	import { mkdir, writeFile } from "node:fs/promises";
 17	import { join } from "node:path";
 18	import { leakedSecretNames, verifyBundle } from "../bundle/index.js";
 19	import { ApprovalsFileSchema } from "../schema/approval.js";
 20	import type { ApprovalRecord } from "../schema/approval.js";
 21	import type { RunBundle } from "../schema/index.js";
 22	import { IncidentsFileSchema, IncidentsIndexSchema } from "../schema/incidents.js";
 23	import type { IncidentsFile, IncidentsIndex } from "../schema/incidents.js";
 24	import type { TimelineEvent } from "../schema/timeline.js";
 25	import { readTimeline } from "../timeline/store.js";
 26	import { withSpan } from "../trace/index.js";
 27	import type { SpanRecord } from "../trace/index.js";
 28	import { resolveTraceLinkTemplate, traceLinkFor } from "../trace/links.js";
 29	import type { TemplateSource } from "../trace/links.js";
 30	import { deriveIncidents } from "./derive.js";
 31	import { reportIncident, reportResolution, reportedIncidentIds } from "./live.js";
 32	
 33	export const INCIDENTS_FILE = "incidents.json";
 34	export const INCIDENTS_INDEX_FILE = "index.json";
 35	
 36	export function incidentsPath(runDir: string): string {
 37	  return join(runDir, INCIDENTS_FILE);
 38	}
 39	
 40	/** runs/<runId>/spans.jsonl records (malformed lines skipped). [] when absent. */
 41	export function readSpanRecords(runDir: string): SpanRecord[] {
 42	  const path = join(runDir, "spans.jsonl");
 43	  if (!existsSync(path)) return [];
 44	  const out: SpanRecord[] = [];
 45	  for (const line of readFileSync(path, "utf8").split(/\r?\n/)) {
 46	    if (!line.trim()) continue;
 47	    try {
 48	      const r = JSON.parse(line) as SpanRecord;
 49	      if (r && typeof r.name === "string" && typeof r.traceId === "string" && typeof r.spanId === "string" && r.attrs && typeof r.attrs === "object") out.push(r);
 50	    } catch {
 51	      // skip malformed lines
 52	    }
 53	  }
 54	  return out;
 55	}
 56	
 57	function readApprovals(runDir: string, runId: string): ApprovalRecord[] {
 58	  const path = join(runDir, "approvals.json");
 59	  if (!existsSync(path)) return [];
 60	  try {
 61	    const parsed = ApprovalsFileSchema.safeParse(JSON.parse(readFileSync(path, "utf8")));
 62	    return parsed.success && parsed.data.runId === runId ? parsed.data.approvals : [];
 63	  } catch {
 64	    return [];
 65	  }
 66	}
 67	
 68	function safeTimeline(runDir: string): TimelineEvent[] {
 69	  try {
 70	    return readTimeline(runDir);
 71	  } catch {
 72	    return [];
 73	  }
 74	}
 75	
 76	/** The IncidentsFile for `bundle`, reading timeline/approvals/spans from `runDir` when given. */
 77	export function buildIncidentsFile(bundle: RunBundle, opts: { runDir?: string; template?: TemplateSource } = {}): IncidentsFile {
 78	  const runDir = opts.runDir && existsSync(opts.runDir) ? opts.runDir : undefined;
 79	  const timeline = runDir ? safeTimeline(runDir) : [];
 80	  const approvals = runDir ? readApprovals(runDir, bundle.runId) : [];
 81	  const spans = runDir ? readSpanRecords(runDir) : [];
 82	  const { template } = opts.template ?? resolveTraceLinkTemplate();
 83	  const sources: IncidentsFile["sources"] = ["bundle"];
 84	  if (timeline.length) sources.push("timeline");
 85	  if (spans.length) sources.push("spans");
 86	  if (approvals.length) sources.push("approvals");
 87	  return IncidentsFileSchema.parse({
 88	    runId: bundle.runId,
 89	    sample: bundle.sample,
 90	    bundleHash: bundle.contentHash,
 91	    sources,
 92	    incidents: deriveIncidents({ bundle, timeline, spans, approvals, traceUrlFor: (id) => traceLinkFor(id, template) }),
 93	  });
 94	}
 95	
 96	function assertNoSecrets(text: string, what: string): void {
 97	  const leaked = leakedSecretNames(text);
 98	  if (leaked.length) throw new Error(`refusing to write ${what}: it contains the value of secret env var(s) ${leaked.join(", ")}`);
 99	}
100	
101	function writeAtomic(path: string, text: string): void {
102	  const tmp = `${path}.tmp-${process.pid}`;
103	  writeFileSync(tmp, text, "utf8");
104	  renameSync(tmp, path);
105	}
106	
107	/**
108	 * Derive + write runs/<runId>/incidents.json and send the incidents to neatlogs (those not already
109	 * reported live in this process, and every resolution). Never throws for tracing problems; a write
110	 * failure is returned in `error` so a finished run is never failed by its incident report.
111	 */
112	export async function recordRunIncidents(bundle: RunBundle, runDir: string, opts: { emit?: boolean } = {}): Promise<{ file: IncidentsFile | null; path: string; emitted: number; error?: string }> {
113	  const path = incidentsPath(runDir);
114	  let file: IncidentsFile;
115	  try {
116	    file = buildIncidentsFile(bundle, { runDir });
117	    const text = `${JSON.stringify(file, null, 2)}\n`;
118	    assertNoSecrets(text, `incidents for ${bundle.runId}`);
119	    mkdirSync(runDir, { recursive: true });
120	    writeAtomic(path, text);
121	  } catch (err) {
122	    return { file: null, path, emitted: 0, error: err instanceof Error ? err.message : String(err) };
123	  }
124	  if (opts.emit === false || file.incidents.length === 0) return { file, path, emitted: 0 };
125	
126	  let emitted = 0;
127	  try {
128	    await withSpan(
129	      "notary.incidents",
130	      {
131	        "notary.incidents.count": file.incidents.length,
132	        "notary.incidents.open": file.incidents.filter((i) => i.resolution.status === "open").length,
133	        "notary.incidents.awaitingHuman": file.incidents.filter((i) => i.resolution.status === "awaiting_human").length,
134	        "notary.incidents.kinds": [...new Set(file.incidents.map((i) => i.kind))].sort().join(","),
135	      },
136	      () => {
137	        const already = reportedIncidentIds();
138	        for (const i of file.incidents) {
139	          if (!already.has(i.id)) {
140	            reportIncident({
141	              id: i.id,
142	              kind: i.kind,
143	              subject: i.recordIds[0] ?? i.id,
144	              severity: i.severity,
145	              summary: i.summary,
146	              ...(i.traceId && i.spanId ? { span: { traceId: i.traceId, spanId: i.spanId } } : {}),
147	              attrs: {
148	                ...(i.agent ? { "notary.agent_id": i.agent } : {}),
149	                ...(i.tool ? { "notary.tool": i.tool } : {}),
150	                ...(i.decisionId ? { "notary.decisionId": i.decisionId } : {}),
151	                ...(i.beliefId ? { "notary.beliefId": i.beliefId } : {}),
152	                ...(i.claimId ? { "notary.claimId": i.claimId } : {}),
153	                "notary.incident.exported": i.exported,
154	              },
155	            });
156	            emitted += 1;
157	          }
158	          if (i.resolution.status !== "open") reportResolution(i.id, i.resolution);
159	        }
160	        return { incidents: file.incidents.length, emitted };
161	      },
162	      { kind: "EVALUATOR" },
163	    );
164	  } catch {
165	    // tracing must never fail a run
166	  }
167	  return { file, path, emitted };
168	}
169	
170	/** One CLI line for a run's incident report. */
171	export function incidentsLine(r: { file: IncidentsFile | null; path: string; emitted: number; error?: string }): string {
172	  if (!r.file) return `incidents: not written (${r.error ?? "unknown error"})`;
173	  const n = r.file.incidents.length;
174	  const open = r.file.incidents.filter((i) => i.resolution.status === "open").length;
175	  const human = r.file.incidents.filter((i) => i.resolution.status === "awaiting_human").length;
176	  return `incidents: ${n} (${n - open - human} resolved, ${human} awaiting a person, ${open} open) -> ${r.path}${r.emitted ? `; ${r.emitted} sent to neatlogs at the end of the run` : ""}`;
177	}
178	
179	/**
180	 * Write `<incidentsDir>/<runId>.json` for a published bundle (verified; sample flag must match). The
181	 * dashboard keeps incidents in their own directory (packages/web/public/incidents[/fixture]), never
182	 * inside public/bundles, whose loaders treat every JSON file as a bundle or timeline.
183	 */
184	export async function publishIncidents(bundle: RunBundle, incidentsDir: string, opts: { expectSample: boolean; runDir?: string; template?: TemplateSource }): Promise<{ path: string; file: IncidentsFile }> {
185	  const v = verifyBundle(bundle);
186	  if (!v.ok) throw new Error(`refusing to publish incidents: ${v.error}`);
187	  if (v.bundle.sample !== opts.expectSample) {
188	    throw new Error(`refusing to publish incidents for ${v.bundle.runId}: sample is ${v.bundle.sample}, expected ${opts.expectSample} (fixture and real data never mix)`);
189	  }
190	  const file = buildIncidentsFile(v.bundle, { ...(opts.runDir ? { runDir: opts.runDir } : {}), ...(opts.template ? { template: opts.template } : {}) });
191	  const text = `${JSON.stringify(file, null, 2)}
192	`;
193	  assertNoSecrets(text, `incidents for ${v.bundle.runId}`);
194	  await mkdir(incidentsDir, { recursive: true });
195	  const path = join(incidentsDir, `${v.bundle.runId}.json`);
196	  await writeFile(path, text, "utf8");
197	  return { path, file };
198	}
199	
200	/** Write `<incidentsDir>/index.json` (IncidentsIndex); all files must share `sample`. Newest run first. */
201	export async function writeIncidentsIndex(incidentsDir: string, files: readonly IncidentsFile[], sample: boolean, startedAt: (runId: string) => string = () => ""): Promise<string> {
202	  for (const f of files) if (f.sample !== sample) throw new Error(`refusing to mix sample and real incidents in one index (${f.runId})`);
203	  const runs = [...files].sort((a, b) => startedAt(b.runId).localeCompare(startedAt(a.runId)) || a.runId.localeCompare(b.runId));
204	  const index: IncidentsIndex = IncidentsIndexSchema.parse({ sample, runs });
205	  const text = `${JSON.stringify(index, null, 2)}
206	`;
207	  assertNoSecrets(text, "incidents index");
208	  await mkdir(incidentsDir, { recursive: true });
209	  const path = join(incidentsDir, INCIDENTS_INDEX_FILE);
210	  await writeFile(path, text, "utf8");
211	  return path;
212	}
213	
214	/**
215	 * Rebuild `<incidentsDir>/index.json` from every `<runId>.json` there whose run is in
216	 * `<bundlesDir>/index.json` with the same sample flag (stale or foreign files are left out).
217	 */
218	export async function rebuildIncidentsIndex(incidentsDir: string, opts: { sample: boolean; bundlesDir: string }): Promise<{ path: string; runs: number; incidents: number }> {
219	  const { BundleIndexSchema } = await import("../schema/bundle.js");
220	  const indexPath = join(opts.bundlesDir, "index.json");
221	  const entries = existsSync(indexPath) ? BundleIndexSchema.safeParse(JSON.parse(readFileSync(indexPath, "utf8"))) : null;
222	  const byRun = new Map((entries?.success ? entries.data : []).filter((e) => e.sample === opts.sample).map((e) => [e.runId, e]));
223	  const files: IncidentsFile[] = [];
224	  for (const name of existsSync(incidentsDir) ? readdirSync(incidentsDir).sort() : []) {
225	    if (!name.endsWith(".json") || name === INCIDENTS_INDEX_FILE) continue;
226	    try {
227	      const parsed = IncidentsFileSchema.safeParse(JSON.parse(readFileSync(join(incidentsDir, name), "utf8")));
228	      if (!parsed.success || parsed.data.sample !== opts.sample || `${parsed.data.runId}.json` !== name) continue;
229	      if (!byRun.has(parsed.data.runId)) continue;
230	      files.push(parsed.data);
231	    } catch {
232	      // unreadable or a directory: left out
233	    }
234	  }
235	  const path = await writeIncidentsIndex(incidentsDir, files, opts.sample, (id) => byRun.get(id)?.startedAt ?? "");
236	  return { path, runs: files.length, incidents: files.reduce((n, f) => n + f.incidents.length, 0) };
237	}
238	
239	/**
240	 * (Re)publish incidents for every bundle already in a dashboard bundles directory (`<bundlesDir>/index.json`
241	 * entries with the given sample flag) into `incidentsDir`, deriving from `<runsDir>/<runId>/` for the
242	 * first runs dir that has the run (bundle-only when none does), then rebuild its index.json. Never
243	 * writes into bundlesDir. Used by `pnpm --filter @notary/core publish:incidents`.
244	 */
245	export async function publishDashboardIncidents(bundlesDir: string, incidentsDir: string, opts: { sample: boolean; runsDirs: readonly string[] }): Promise<{ published: string[]; skipped: { runId: string; reason: string }[]; index: { path: string; runs: number; incidents: number } }> {
246	  const { BundleIndexSchema } = await import("../schema/bundle.js");
247	  const indexPath = join(bundlesDir, "index.json");
248	  const parsed = existsSync(indexPath) ? BundleIndexSchema.safeParse(JSON.parse(readFileSync(indexPath, "utf8"))) : null;
249	  const published: string[] = [];
250	  const skipped: { runId: string; reason: string }[] = [];
251	  for (const e of parsed?.success ? parsed.data : []) {
252	    if (e.sample !== opts.sample || e.kind === "sample") continue;
253	    try {
254	      const v = verifyBundle(JSON.parse(readFileSync(join(bundlesDir, `${e.runId}.json`), "utf8")));
255	      if (!v.ok) {
256	        skipped.push({ runId: e.runId, reason: v.error });
257	        continue;
258	      }
259	      const runDir = opts.runsDirs.map((r) => join(r, e.runId)).find((p) => existsSync(p));
260	      await publishIncidents(v.bundle, incidentsDir, { expectSample: opts.sample, ...(runDir ? { runDir } : {}) });
261	      published.push(e.runId);
262	    } catch (err) {
263	      skipped.push({ runId: e.runId, reason: err instanceof Error ? err.message : String(err) });
264	    }
265	  }
266	  return { published, skipped, index: await rebuildIncidentsIndex(incidentsDir, { sample: opts.sample, bundlesDir }) };
267	}
268	/**
269	 * Live incident events in neatlogs. When something goes wrong while an agent works, the call site
270	 * reports it here and it becomes a neatlogs log() record at level warn/error, tied to the span that
271	 * is active at that moment (the probe, the guard, the LLM call, ...):
272	 *
273	 *   message   "incident <kind> [WARN|ERROR]: <summary>"
274	 *   attrs     notary.incident.id / .kind / .severity / .subject, notary.incident.spanId / .traceId
275	 *             (the span it happened in), notary.runId, plus small call-site facts
276	 *             (the SDK records each as a `log.<key>` attribute)
277	 *
278	 * Resolutions are logged the same way at level info ("incident <id> resolved: <summary>").
279	 *
280	 * The incident id is deterministic — incidentId(kind, subject) — and src/incidents/derive.ts uses
281	 * the same function on the recorded data, so the log event in neatlogs and the row in
282	 * runs/<runId>/incidents.json carry the same `notary.incident.id`. At the end of a run,
283	 * recordRunIncidents emits every derived incident that was not already reported live in this process
284	 * (so each incident reaches neatlogs exactly once per process).
285	 *
286	 * Never throws; no-op (returns false) when tracing is off. Summaries are generated by code and pass
287	 * through the trace module's secret masking.
288	 */
289	import { createHash } from "node:crypto";
290	import type { IncidentKind, IncidentResolution, IncidentSeverity } from "../schema/incidents.js";
291	import { currentSpanIds, traceLogAt } from "../trace/index.js";
292	import type { TraceAttrs } from "../trace/index.js";
293	
294	/** "inc-" + sha256(kind | subject)[:16]. Subjects are globally unique record keys (anomaly id, probe id, span id, ...). */
295	export function incidentId(kind: IncidentKind, subject: string): string {
296	  return `inc-${createHash("sha256").update(`${kind}|${subject}`).digest("hex").slice(0, 16)}`;
297	}
298	
299	const reported = new Set<string>();
300	const resolved = new Set<string>();
301	
302	/** Incident ids already sent to neatlogs by this process. */
303	export function reportedIncidentIds(): ReadonlySet<string> {
304	  return reported;
305	}
306	
307	/** Forget what was reported (tests). */
308	export function resetReportedIncidents(): void {
309	  reported.clear();
310	  resolved.clear();
311	}
312	
313	export function logLevelFor(severity: IncidentSeverity): "warn" | "error" {
314	  return severity === "error" ? "error" : "warn";
315	}
316	
317	export type LiveIncident = {
318	  kind: IncidentKind;
319	  /** The record key the id is derived from (must match what derive.ts uses for this kind). */
320	  subject: string;
321	  severity: IncidentSeverity;
322	  summary: string;
323	  /** Extra facts (ids, status codes, ...). Never secrets or prompts. */
324	  attrs?: TraceAttrs;
325	  /** The span it happened in, when not the active one. */
326	  span?: { traceId: string; spanId: string };
327	  /** A precomputed id (derive.ts); default incidentId(kind, subject). */
328	  id?: string;
329	};
330	
331	/** Send one incident to neatlogs as a warn/error log record. Returns its id. Idempotent per process. */
332	export function reportIncident(i: LiveIncident): string {
333	  const id = i.id ?? incidentId(i.kind, i.subject);
334	  if (reported.has(id)) return id;
335	  try {
336	    const span = i.span ?? currentSpanIds();
337	    const ok = traceLogAt(logLevelFor(i.severity), `incident ${i.kind} [${i.severity === "error" ? "ERROR" : "WARN"}]: ${i.summary}`, {
338	      "notary.incident.id": id,
339	      "notary.incident.kind": i.kind,
340	      "notary.incident.severity": i.severity,
341	      "notary.incident.subject": i.subject,
342	      ...(span ? { "notary.incident.traceId": span.traceId, "notary.incident.spanId": span.spanId } : {}),
343	      ...i.attrs,
344	    });
345	    if (ok) reported.add(id);
346	  } catch {
347	    // incident reporting must never break the traced work
348	  }
349	  return id;
350	}
351	
352	/** Log how an incident was resolved (level info). Idempotent per (id, action) per process. */
353	export function reportResolution(id: string, r: Pick<IncidentResolution, "status" | "action" | "summary"> & { recordIds?: string[] }): void {
354	  const key = `${id}|${r.action}`;
355	  if (resolved.has(key)) return;
356	  try {
357	    const ok = traceLogAt("info", `incident ${id} ${r.status === "resolved" ? "resolved" : r.status.replace("_", " ")}: ${r.summary}`, {
358	      "notary.incident.id": id,
359	      "notary.incident.resolution": r.status,
360	      "notary.incident.resolution.action": r.action,
361	      ...(r.recordIds?.length ? { "notary.incident.resolution.records": r.recordIds.join(",") } : {}),
362	    });
363	    if (ok) resolved.add(key);
364	  } catch {
365	    // never break the traced work
366	  }
367	}
368	/**
369	 * Live incidents for one queue decision, reported by the executor inside the item's AGENT span:
370	 * a guard hold (a money action held because required beliefs are not notarized) is a warn log in
371	 * neatlogs, immediately followed by its resolution so far ("held for a person"). Same id as
372	 * derive.ts's guard_hold (subject = decision id). Guard firings (block / transform / precheck) are
373	 * reported where they happen, in src/guards/guarded.ts.
374	 */
375	import type { Decision, QueueRequest } from "../schema/index.js";
376	import { incidentId, reportIncident, reportResolution } from "./live.js";
377	
378	export function reportDecisionIncidents(d: Decision, req?: Pick<QueueRequest, "amount" | "currency">): void {
379	  try {
380	    if (d.status !== "held" || d.missingBeliefs.length === 0) return;
381	    const amount = req?.amount === undefined ? "an unknown amount" : `${req.amount} ${req.currency ?? ""} (minor units)`.replace("  ", " ");
382	    const id = reportIncident({
383	      kind: "guard_hold",
384	      subject: d.id,
385	      severity: "warning",
386	      summary: `The Guard held ${d.action} for ${d.requestId} (${amount}): ${d.missingBeliefs.length} required belief(s) not notarized (${d.missingBeliefs.join(", ")}).`,
387	      attrs: { "notary.decisionId": d.id, "notary.requestId": d.requestId, "notary.guard.action": d.action, "notary.guard.missingBeliefs": d.missingBeliefs.join(","), "notary.agent_id": "guard" },
388	    });
389	    reportResolution(id || incidentId("guard_hold", d.id), {
390	      status: "awaiting_human",
391	      action: "held_for_person",
392	      summary: `Held with an evidence pack (${d.evidencePack?.relatedProbeIds.length ?? 0} related probe(s)) for a person in Approvals.`,
393	      recordIds: [d.id],
394	    });
395	  } catch {
396	    // never break the run
397	  }
398	}
399	export { deriveIncidents } from "./derive.js";
400	export type { DeriveIncidentsInput } from "./derive.js";
