 48	/** sha256 hex of canonicalJson(file without contentHash). Same rule as run bundles. */
 49	export function economicsHash(body: EconomicsBody | EconomicsFile): string {
 50	  const { contentHash: _ignored, ...rest } = body as EconomicsFile;
 51	  return sha256Hex(canonicalJson(rest));
 52	}
 53	
 54	/** Validate the body and stamp its content hash. */
 55	export function finalizeEconomics(body: EconomicsBody): EconomicsFile {
 56	  const parsed = EconomicsBodyCheckedSchema.parse(body);
 57	  return EconomicsFileSchema.parse({ ...parsed, contentHash: economicsHash(parsed) });
 58	}
 59	
 60	export type EconomicsVerify = { ok: true; file: EconomicsFile } | { ok: false; error: string };
 61	
 62	export function verifyEconomics(raw: unknown): EconomicsVerify {
 63	  const parsed = EconomicsFileSchema.safeParse(raw);
 64	  if (!parsed.success) return { ok: false, error: `economics.json fails its schema: ${parsed.error.issues.map((i) => `${i.path.join(".")}: ${i.message}`).join("; ")}` };
 65	  const actual = economicsHash(parsed.data);
 66	  if (actual !== parsed.data.contentHash) return { ok: false, error: `economics.json content hash mismatch: recorded ${parsed.data.contentHash}, computed ${actual}` };
 67	  return { ok: true, file: parsed.data };
 68	}
