 70	interface Source {
 71	  bundle: RunBundle;
 72	  file: string;
 73	}
 74	
 75	/** Top-level <runId>.json files of the published dashboard dir (never fixture/, never timelines). */
 76	function publishedBundles(dir: string): { bundles: Source[]; skipped: { file: string; reason: string }[] } {
 77	  const out = { bundles: [] as Source[], skipped: [] as { file: string; reason: string }[] };
 78	  if (!existsSync(dir)) return out;
 79	  for (const name of readdirSync(dir).sort()) {
 80	    if (!name.endsWith(".json") || name === "index.json" || name.endsWith(".timeline.json")) continue;
 81	    const file = `web/public/bundles/${name}`;
 82	    let raw: unknown;
 83	    try {
 84	      raw = JSON.parse(readFileSync(join(dir, name), "utf8"));
 85	    } catch {
 86	      out.skipped.push({ file, reason: "unreadable JSON" });
 87	      continue;
 88	    }
 89	    const v = verifyBundle(raw);
 90	    if (!v.ok) {
 91	      out.skipped.push({ file, reason: v.reason === "hash" ? "content hash mismatch (tampered or edited after writing)" : "fails the bundle schema" });
 92	      continue;
 93	    }
 94	    const b = v.bundle;
 95	    if (b.sample || b.kind === "sample" || b.variant === "sample") {
 96	      out.skipped.push({ file, reason: "SAMPLE/fixture bundle — never a source of results" });
 97	      continue;
 98	    }
 99	    if (name.replace(/\.json$/, "") !== b.runId) {
100	      out.skipped.push({ file, reason: `file name does not match its runId (${b.runId})` });
101	      continue;
102	    }
103	    out.bundles.push({ bundle: b, file });
104	  }
105	  return out;
106	}
