214	/** Read and parse an export file from disk (bytes hashed as read). */
215	export function importCfoPlanFile(path: string, importedAt: string): CfoPlan {
216	  const bytes = readFileSync(path);
217	  return parseCfoPlanCsv({ text: bytes.toString("utf8"), file: path, importedAt, fileSha256: sha256Hex(new Uint8Array(bytes)) });
218	}
