147	export function explainCheckpoint(exec: Exec, cwd: string, id: string): CheckpointDetail | null {
148	  const r = exec(["checkpoint", "explain", id, "--json"], cwd);
149	  if (!ok(r)) return null;
150	  const v = json(r.stdout) as
151	    | {
152	        files_touched?: unknown;
153	        sessions?: Array<{
154	          model?: unknown;
155	          token_usage?: { input_tokens?: number; output_tokens?: number; cache_read_tokens?: number; cache_creation_tokens?: number; api_call_count?: number };
156	        }>;
157	      }
158	    | undefined;
