160	  const files = Array.isArray(v.files_touched) ? v.files_touched.filter((f): f is string => typeof f === "string" && f.length > 0) : [];
161	  const sessions = Array.isArray(v.sessions) ? v.sessions : [];
162	  const model = sessions.map((s) => s.model).find((m): m is string => typeof m === "string" && m.length > 0) ?? null;
163	  const usages = sessions.map((s) => s.token_usage).filter((u): u is NonNullable<typeof u> => !!u && typeof u === "object");
164	  const n = (x: unknown): number => (typeof x === "number" && Number.isFinite(x) && x >= 0 ? Math.round(x) : 0);
165	  const tokens = usages.length
166	    ? usages.reduce(
167	        (acc, u) => ({
