169	          output: acc.output + n(u.output_tokens),
170	          cacheRead: acc.cacheRead + n(u.cache_read_tokens),
171	          cacheCreation: acc.cacheCreation + n(u.cache_creation_tokens),
172	          apiCalls: acc.apiCalls + n(u.api_call_count),
173	        }),
174	        { input: 0, output: 0, cacheRead: 0, cacheCreation: 0, apiCalls: 0 },
