185	/** checkpoint id -> commit (sha, subject), from the `Entire-Checkpoint` trailers on the current branch. */
186	export function checkpointCommits(git: Exec, cwd: string): Map<string, CheckpointCommit> {
187	  const r = git(["log", "--format=%H%x1f%s%x1f%(trailers:key=Entire-Checkpoint,valueonly,separator=%x2C)%x1e"], cwd);
188	  const out = new Map<string, CheckpointCommit>();
189	  if (!ok(r)) return out;
190	  for (const rec of r.stdout.split("\x1e")) {
191	    const [sha, subject, ids] = rec.trim().split("\x1f");
192	    if (!sha || !/^[0-9a-f]{40}$/.test(sha) || !ids) continue;
193	    for (const id of ids.split(",").map((x) => x.trim()).filter(Boolean)) if (!out.has(id)) out.set(id, { sha, subject: subject ?? "" });
194	  }
195	  return out;
196	}
