211	export function toCheckpoint(raw: RawCheckpoint, detail: CheckpointDetail | null, commit: CheckpointCommit | undefined): EntireCheckpoint | null {
212	  if (!commit || !EntireCheckpointIdSchema.safeParse(raw.checkpoint_id).success) return null;
213	  const at = raw.date ? new Date(raw.date) : undefined;
214	  if (!at || Number.isNaN(at.getTime())) return null;
215	  const sessionIds = [...new Set([...(raw.session_ids ?? []), ...(raw.session_id ? [raw.session_id] : [])].filter((x) => typeof x === "string" && x.length > 0))];
