280	  const br = git(["rev-parse", "--abbrev-ref", "HEAD"], root);
281	  const branch = ok(br) && br.stdout.trim() && br.stdout.trim() !== "HEAD" ? br.stdout.trim() : null;
282	  const settings = readEntireSettings(root);
283	
284	  const version = entireCliVersion(entire, root);
285	  if (!version) {
286	    return EntireFileSchema.parse({
287	      kind: ENTIRE_FILE_KIND,
288	      repoHead,
