158	const SECRET_ENV_RE = /(KEY|TOKEN|SECRET|PASSWORD|PASSWD|CREDENTIAL)/i;
159	
160	/** Replaces the value of every secret-looking env var (length ≥ 8, longest first) with [REDACTED]. */
161	export function scrubber(env: Env): (text: string) => string {
162	  const secrets = Object.entries(env)
163	    .filter(([name, v]) => SECRET_ENV_RE.test(name) && (v?.trim().length ?? 0) >= 8)
164	    .map(([, v]) => v!.trim())
165	    .sort((a, b) => b.length - a.length);
166	  return (text) => {
167	    let out = text;
168	    for (const s of secrets) if (out.includes(s)) out = out.split(s).join("[REDACTED]");
169	    return out;
170	  };
171	}
