173	/**
174	 * The scrubber for streamed text: a secret split across deltas is still replaced. `push` returns the
175	 * text safe to pass on now, holding back a tail that could be the start of a secret; `end` flushes it.
176	 */
177	export function streamScrubber(env: Env): { push: (delta: string) => string; end: () => string } {
178	  const secrets = Object.entries(env)
179	    .filter(([name, v]) => SECRET_ENV_RE.test(name) && (v?.trim().length ?? 0) >= 8)
180	    .map(([, v]) => v!.trim());
181	  const clean = scrubber(env);
182	  let buf = "";
183	  return {
184	    push(delta) {
185	      buf = clean(buf + delta);
186	      let hold = 0;
187	      for (const s of secrets) {
188	        for (let k = Math.min(s.length - 1, buf.length); k > hold; k--) {
189	          if (buf.endsWith(s.slice(0, k))) {
190	            hold = k;
191	            break;
192	          }
193	        }
194	      }
195	      const out = buf.slice(0, buf.length - hold);
196	      buf = buf.slice(buf.length - hold);
197	      return out;
198	    },
199	    end() {
200	      const out = clean(buf);
201	      buf = "";
202	      return out;
203	    },
204	  };
205	}
