229	/** Per-role token and USD accounting. */
230	export class UsageMeter {
231	  private readonly usage: UsageByRole = {
232	    executor: { inputTokens: 0, outputTokens: 0, usd: 0, calls: 0 },
233	    reflector: { inputTokens: 0, outputTokens: 0, usd: 0, calls: 0 },
234	    adversary: { inputTokens: 0, outputTokens: 0, usd: 0, calls: 0 },
235	  };
236	  /** Notary Chat's usage: counted by totalUsd() (NOTARY_MAX_USD), never part of snapshot(). */
237	  private readonly chat = { inputTokens: 0, outputTokens: 0, usd: 0, calls: 0 };
238	  /** Pricing problems (unknown model, bad override). De-duplicated. */
239	  readonly warnings: string[] = [];
240	
241	  add(role: ModelRole, u: { inputTokens: number; outputTokens: number; usd: number }): void {
242	    const r = role === "chat" ? this.chat : this.usage[role];
243	    r.inputTokens += u.inputTokens;
244	    r.outputTokens += u.outputTokens;
245	    r.usd = Math.round((r.usd + u.usd) * 1e9) / 1e9;
246	    r.calls += 1;
247	  }
248	
249	  warn(message: string): void {
250	    if (this.warnings.includes(message)) return;
251	    this.warnings.push(message);
252	    warnOnce(message);
253	  }
254	
255	  /** USD recorded so far across all roles (the run's model spend). */
256	  totalUsd(): number {
257	    return Math.round((this.usage.executor.usd + this.usage.reflector.usd + this.usage.adversary.usd + this.chat.usd) * 1e9) / 1e9;
258	  }
259	
260	  /** Notary Chat's usage (not part of any bundle). A copy. */
261	  chatUsage(): { inputTokens: number; outputTokens: number; usd: number; calls: number } {
262	    return { ...this.chat };
263	  }
264	
265	  /** The bundle's `usageByRole` shape, always with all three roles. A copy. */
266	  snapshot(): UsageByRole {
267	    const out = {} as UsageByRole;
268	    for (const role of ROLES) out[role] = { ...this.usage[role] };
269	    return out;
270	  }
271	}
