273	/** Default transport: the real Bedrock Runtime client, created lazily on the first call. */
274	export function bedrockTransport(region: string): ConverseTransport {
275	  let client: { send: (cmd: unknown, opts?: { abortSignal?: AbortSignal }) => Promise<unknown> } | null = null;
276	  let ConverseCommandCtor: (new (input: ConverseCommandInput) => unknown) | null = null;
277	  return async (input, opts) => {
278	    if (!client || !ConverseCommandCtor) {
279	      const sdk = await import("@aws-sdk/client-bedrock-runtime");
280	      // wrapBedrock (when tracing is on) emits the LLM span with messages, completion and usage.
281	      client = traceBedrockClient(new sdk.BedrockRuntimeClient({ region })) as unknown as typeof client;
282	      ConverseCommandCtor = sdk.ConverseCommand;
283	    }
284	    const cmd = new ConverseCommandCtor!(input);
285	    return (await (opts?.abortSignal ? client!.send(cmd, { abortSignal: opts.abortSignal }) : client!.send(cmd))) as ConverseCommandOutput;
286	  };
287	}
