 36	 * (`stream: true`, `stream_options.include_usage`), each text delta passed on as it arrives. The
 37	 * reply is still returned whole (a completion assembled from the chunks), so pricing, usage and
 38	 * stop reasons are identical to the non-streamed path.
 39	 */
 40	export type ChatCallOptions = { signal?: AbortSignal; onDelta?: (delta: string) => void };
 41	/** Sends one chat completion. Injectable so tests never reach a proxy. */
 42	export type ChatTransport = (body: ChatRequest, opts?: ChatCallOptions) => Promise<ChatReply>;
 43	/** Lists the model ids the proxy offers (GET <base>/v1/models). Injectable for tests. */
 44	export type ModelLister = () => Promise<string[]>;
