 46	/** Response headers kept from a chat completion. */
 47	export const KEPT_RESPONSE_HEADERS = ["x-litellm-response-cost", "retry-after", "retry-after-ms", "x-ratelimit-reset"] as const;
 48	/** Per-request correlation header (stripped by the fetch wrapper; never sent). */
 49	const CALL_HEADER = "x-notary-call-id";
 50	/** Per-request timeout. Long replies (the reflector may write up to 8000 tokens) need minutes. */
 51	export const LITELLM_TIMEOUT_MS = 300_000;
