 53	type CreateOpts = { headers?: Record<string, string>; signal?: AbortSignal };
 54	/** One streamed chunk (the fields Notary reads). */
 55	type StreamChunk = {
 56	  id?: string;
 57	  model?: string;
 58	  created?: number;
 59	  choices?: {
 60	    delta?: { content?: string | null; tool_calls?: { index?: number; id?: string; type?: string; function?: { name?: string; arguments?: string } }[] | null };
 61	    finish_reason?: string | null;
 62	  }[];
 63	  usage?: ChatCompletion["usage"] | null;
 64	};
 65	type OpenAiClient = {
 66	  chat: { completions: { create: (body: ChatRequest | Record<string, unknown>, opts?: CreateOpts) => Promise<ChatCompletion | AsyncIterable<StreamChunk>> } };
 67	  models: { list: () => Promise<{ data: { id: string }[] }> & AsyncIterable<{ id: string }> };
 68	};
