 70	function pick(headers: Headers): Record<string, string> {
 71	  const out: Record<string, string> = {};
 72	  for (const name of KEPT_RESPONSE_HEADERS) {
 73	    const v = headers.get(name);
 74	    if (v !== null) out[name] = v;
 75	  }
 76	  return out;
 77	}
