 79	/** A lazily built `openai` client for one proxy, plus the header side channel. */
 80	function lazyClient(opts: { baseUrl: string; apiKey: string; fetch?: typeof fetch }) {
 81	  let client: OpenAiClient | null = null;
 82	  const captured = new Map<string, Record<string, string>>();
 83	  const baseFetch = opts.fetch ?? globalThis.fetch;
 84	  const capturingFetch: typeof fetch = async (input, init) => {
 85	    const headers = new Headers(init?.headers);
 86	    const id = headers.get(CALL_HEADER);
 87	    if (id !== null) headers.delete(CALL_HEADER);
 88	    const res = await baseFetch(input, { ...init, headers });
 89	    if (id !== null) captured.set(id, pick(res.headers));
 90	    return res;
 91	  };
 92	  const get = async (): Promise<OpenAiClient> => {
 93	    if (client) return client;
 94	    const { default: OpenAI } = await import("openai");
 95	    let c = new OpenAI({
 96	      baseURL: opts.baseUrl,
 97	      apiKey: opts.apiKey,
 98	      maxRetries: 0,
 99	      timeout: LITELLM_TIMEOUT_MS,
100	      fetch: capturingFetch,
101	    }) as unknown as OpenAiClient;
102	    if (tracingEnabled()) {
103	      try {
104	        const { wrapOpenAI } = await import("neatlogs");
105	        c = wrapOpenAI(c);
106	      } catch {
107	        // tracing must never break the call
108	      }
109	    }
110	    client = c;
111	    return c;
112	  };
113	  return { get, captured };
