116	/** Default LiteLLM transport: the real proxy through `openai`, created on the first call. */
117	export function liteLlmTransport(opts: { baseUrl: string; apiKey: string; fetch?: typeof fetch }): ChatTransport {
118	  const lazy = lazyClient(opts);
119	  return async (body, opts) => {
120	    const client = await lazy.get();
121	    const id = randomUUID();
122	    const reqOpts: CreateOpts = { headers: { [CALL_HEADER]: id }, ...(opts?.signal ? { signal: opts.signal } : {}) };
123	    try {
124	      if (!opts?.onDelta) {
125	        const completion = (await client.chat.completions.create(body, reqOpts)) as ChatCompletion;
126	        return { completion, headers: lazy.captured.get(id) ?? {} };
127	      }
128	      const stream = (await client.chat.completions.create({ ...body, stream: true, stream_options: { include_usage: true } }, reqOpts)) as AsyncIterable<StreamChunk>;
129	      const completion = await collectStream(stream, opts.onDelta, body.model);
130	      return { completion, headers: lazy.captured.get(id) ?? {} };
131	    } finally {
132	      lazy.captured.delete(id);
133	    }
134	  };
135	}
