137	/** Read a streamed chat completion, passing each text delta on, and assemble the whole completion. */
138	export async function collectStream(stream: AsyncIterable<StreamChunk>, onDelta: (delta: string) => void, model: string): Promise<ChatCompletion> {
139	  let text = "";
140	  let finish: string | null = null;
141	  let usage: ChatCompletion["usage"] | undefined;
142	  let id = "";
143	  let created = 0;
144	  let modelId = model;
145	  const calls = new Map<number, { id: string; name: string; arguments: string }>();
146	  for await (const chunk of stream) {
147	    if (chunk.id) id = chunk.id;
148	    if (chunk.created) created = chunk.created;
149	    if (chunk.model) modelId = chunk.model;
150	    if (chunk.usage) usage = chunk.usage;
151	    const choice = chunk.choices?.[0];
152	    const delta = choice?.delta?.content;
153	    if (typeof delta === "string" && delta.length > 0) {
154	      text += delta;
155	      onDelta(delta);
156	    }
157	    for (const tc of choice?.delta?.tool_calls ?? []) {
158	      const i = tc.index ?? 0;
159	      const cur = calls.get(i) ?? { id: "", name: "", arguments: "" };
160	      if (tc.id) cur.id = tc.id;
161	      if (tc.function?.name) cur.name += tc.function.name;
162	      if (tc.function?.arguments) cur.arguments += tc.function.arguments;
163	      calls.set(i, cur);
164	    }
165	    if (choice?.finish_reason) finish = choice.finish_reason;
166	  }
167	  const toolCalls = [...calls.entries()]
168	    .sort(([a], [b]) => a - b)
169	    .map(([, c]) => ({ id: c.id, type: "function" as const, function: { name: c.name, arguments: c.arguments } }));
170	  return {
171	    id,
172	    object: "chat.completion",
173	    created,
174	    model: modelId,
175	    choices: [
176	      {
177	        index: 0,
178	        message: { role: "assistant", content: text, refusal: null, ...(toolCalls.length ? { tool_calls: toolCalls } : {}) },
179	        finish_reason: (finish ?? "stop") as "stop",
180	        logprobs: null,
181	      },
182	    ],
183	    ...(usage ? { usage } : {}),
184	  } as ChatCompletion;
185	}
