217	/**
218	 * USD per 1M input / output tokens, per model id.
219	 *
220	 * Resolution order for a call made by `role` with `modelId` (`priceCall`):
221	 *   1. env overrides NOTARY_PRICE_<ROLE>_IN and NOTARY_PRICE_<ROLE>_OUT (USD per 1M tokens; both
222	 *      must be set and be non-negative numbers) — they apply to any model id, LiteLLM names included,
223	 *   2. the cost the LiteLLM proxy reports for that response (`x-litellm-response-cost` header, USD),
224	 *   3. the table below (Bedrock model ids only),
225	 *   4. otherwise the price is unknown: usd = 0, price source "unknown", and a warning naming the
226	 *      env vars is recorded on the meter and printed once per process. Notary never guesses a
227	 *      price; set the env override for any model not listed.
228	 *
229	 * Sources (checked 2026-10-10):
230	 *   - AWS Bedrock pricing: https://aws.amazon.com/bedrock/pricing/  (authoritative for Bedrock)
231	 *   - Anthropic model pricing: https://platform.claude.com/docs/en/about-claude/pricing — lists the
232	 *     base input/output price per MTok used below, and states that from Claude Sonnet 4.5 / Haiku 4.5
233	 *     / Opus 4.5 onward, Bedrock regional (geo / in-region) endpoints carry a 10% premium over
234	 *     global endpoints; Opus 4.1 and earlier keep a single price.
235	 * The Bedrock page's price tables did not render for an automated fetch, so the figures are the
236	 * Anthropic list prices for Bedrock global endpoints. Only model ids whose exact Bedrock id is
237	 * known are listed; anything else (including newer models) needs the env override.
238	 */
239	import type { ModelRole } from "./roles.js";
240	import { baseModelId } from "./roles.js";
241	import { AGENTS } from "../schema/agents.js";
242	
243	export type ModelPrice = {
244	  /** USD per 1M input tokens. */
245	  inPerM: number;
246	  /** USD per 1M output tokens. */
247	  outPerM: number;
248	};
249	
250	type TableEntry = ModelPrice & {
251	  /** True for models priced +10% on regional/geo endpoints vs. "global." (Claude 4.5 and later). */
252	  regionalPremium: boolean;
253	};
254	
255	export const BEDROCK_PRICING_URL = "https://aws.amazon.com/bedrock/pricing/";
256	export const REGIONAL_PREMIUM = 1.1;
257	
258	/** Keyed by bare Bedrock model id (no geo prefix), lowercased. */
259	export const PRICE_TABLE: Readonly<Record<string, TableEntry>> = {
260	  "anthropic.claude-opus-4-5-20251101-v1:0": { inPerM: 5, outPerM: 25, regionalPremium: true },
261	  "anthropic.claude-sonnet-4-5-20250929-v1:0": { inPerM: 3, outPerM: 15, regionalPremium: true },
262	  "anthropic.claude-haiku-4-5-20251001-v1:0": { inPerM: 1, outPerM: 5, regionalPremium: true },
263	  "anthropic.claude-opus-4-1-20250805-v1:0": { inPerM: 15, outPerM: 75, regionalPremium: false },
264	  "anthropic.claude-opus-4-20250514-v1:0": { inPerM: 15, outPerM: 75, regionalPremium: false },
265	  "anthropic.claude-sonnet-4-20250514-v1:0": { inPerM: 3, outPerM: 15, regionalPremium: false },
266	  "anthropic.claude-3-5-haiku-20241022-v1:0": { inPerM: 0.8, outPerM: 4, regionalPremium: false },
267	};
268	
269	export type PriceSource = "env" | "litellm" | "table" | "unknown";
270	
271	export type ResolvedPrice = {
272	  price: ModelPrice | null;
273	  source: PriceSource;
274	  /** Set when the price could not be resolved (usd will be recorded as 0). */
275	  warning?: string;
276	};
277	
278	type Env = Record<string, string | undefined>;
279	
280	function envNumber(env: Env, name: string): number | undefined | "invalid" {
281	  const raw = (env[name] ?? "").trim();
282	  if (!raw) return undefined;
283	  const n = Number(raw);
284	  return Number.isFinite(n) && n >= 0 ? n : "invalid";
285	}
