287	export function resolvePrice(role: ModelRole, modelId: string, env: Env = process.env): ResolvedPrice {
288	  const inName = `NOTARY_PRICE_${role.toUpperCase()}_IN`;
289	  const outName = `NOTARY_PRICE_${role.toUpperCase()}_OUT`;
290	  const inP = envNumber(env, inName);
291	  const outP = envNumber(env, outName);
292	  if (inP !== undefined || outP !== undefined) {
293	    if (typeof inP === "number" && typeof outP === "number") {
294	      return { price: { inPerM: inP, outPerM: outP }, source: "env" };
295	    }
296	    return {
297	      price: null,
298	      source: "unknown",
299	      warning: `${inName} and ${outName} must both be non-negative numbers (USD per 1M tokens); usd recorded as 0 for the ${AGENTS[role].name}`,
300	    };
301	  }
302	
303	  const entry = PRICE_TABLE[baseModelId(modelId)];
304	  if (entry) {
305	    const isGlobal = /^global\./i.test(modelId.trim());
306	    const mult = entry.regionalPremium && !isGlobal ? REGIONAL_PREMIUM : 1;
307	    return { price: { inPerM: entry.inPerM * mult, outPerM: entry.outPerM * mult }, source: "table" };
308	  }
309	  return {
310	    price: null,
311	    source: "unknown",
312	    warning: `No price for model "${modelId}" (${AGENTS[role].name}); usd recorded as 0. Set ${inName} and ${outName} (USD per 1M tokens; Bedrock list prices: ${BEDROCK_PRICING_URL})`,
313	  };
314	}
