316	/** The proxy-reported cost of one response (USD), or null when absent / unusable. */
317	export function reportedCostUsd(headers: Record<string, string> | undefined): number | null {
318	  const raw = headers?.["x-litellm-response-cost"]?.trim();
319	  if (!raw) return null;
320	  const n = Number(raw);
321	  return Number.isFinite(n) && n >= 0 ? n : null;
322	}
