331	/**
332	 * USD for one finished call, by precedence: env override > LiteLLM-reported > table > unknown (0).
333	 * `reportedUsd` is the proxy's own figure for this response, when it sent one.
334	 */
335	export function priceCall(
336	  role: ModelRole,
337	  modelId: string,
338	  tokens: { inputTokens: number; outputTokens: number },
339	  env: Env = process.env,
340	  reportedUsd: number | null = null,
341	): PricedCall {
342	  const r = resolvePrice(role, modelId, env);
343	  if (r.source === "env") return { usd: costUsd(r.price, tokens.inputTokens, tokens.outputTokens), source: "env" };
344	  // A half-set override is a config error: keep its warning even if the proxy reported a cost.
345	  const halfSet = r.warning && /must both be/.test(r.warning) ? { warning: r.warning } : {};
346	  if (reportedUsd !== null) return { usd: Math.round(reportedUsd * 1e9) / 1e9, source: "litellm", ...halfSet };
347	  if (r.source === "table") return { usd: costUsd(r.price, tokens.inputTokens, tokens.outputTokens), source: "table" };
348	  return { usd: 0, source: "unknown", ...(r.warning ? { warning: r.warning } : {}) };
349	}
350	
351	/** USD for one call; 0 when the price is unknown. Rounded to 1e-9 to keep sums stable. */
352	export function costUsd(price: ModelPrice | null, inputTokens: number, outputTokens: number): number {
353	  if (!price) return 0;
354	  const usd = (inputTokens * price.inPerM + outputTokens * price.outPerM) / 1_000_000;
355	  return Math.round(usd * 1e9) / 1e9;
356	}
357	/**
358	 * Hard per-run USD cap for model calls: NOTARY_MAX_USD (USD; unset = no cap).
359	 *
360	 * "Per run" = per LlmClient: one notarize run (or compare-priors arm pair, or one Ask Notary
361	 * question) builds one client, whose UsageMeter is the run's spend. Before every model call —
362	 * and before every retry of it — the client checks
363	 *
364	 *     spent + estimate(this call) > cap   (or spent ≥ cap)   →  UsdCapExceededError
365	 *
366	 * where `estimate` is a deliberately high upper bound when the role's price is known up front (env
367	 * override or the Bedrock table): input tokens ≈ prompt characters / 2 (real tokenizers average
368	 * 3–4 characters per token) plus the full output-token cap (maxTokens). With an unknown price (e.g. a
369	 * LiteLLM model with no NOTARY_PRICE_* override) the estimate is 0, so the cap is enforced on spend
370	 * already recorded — including the cost LiteLLM reports per response — and the call that crosses
371	 * it is the last one. The error is thrown before any network I/O, so it never costs anything.
372	 *
373	 * Callers stop cleanly on it the way they stop on Crustdata's BudgetExceededError: the probe loop
374	 * and the adversary phase record it as the run's stopReason and the bundle ends `stopped_budget`;
375	 * Ask Notary returns its ok:false answer with the message as the reason. Replay re-throws the
376	 * recorded error by name, so `isUsdCapExceeded` matches on the name, not the class.
377	 */
378	import { ModelConfigError } from "./roles.js";
379	import { AGENTS } from "../schema/agents.js";
380	
381	type Env = Record<string, string | undefined>;
382	
383	export const MAX_USD_ENV = "NOTARY_MAX_USD";
384	/** Characters per token assumed by the pre-call estimate (low on purpose, so the estimate is high). */
385	export const ESTIMATE_CHARS_PER_TOKEN = 2;
386	
387	/** The configured cap in USD, or null for no cap. Throws ModelConfigError for an unusable value. */
388	export function maxUsdFromEnv(env: Env = process.env): number | null {
389	  const raw = (env[MAX_USD_ENV] ?? "").trim();
390	  if (!raw) return null;
391	  const n = Number(raw);
392	  if (!Number.isFinite(n) || n < 0) {
393	    throw new ModelConfigError(`${MAX_USD_ENV} must be a non-negative number of USD per run (got "${raw}"); fix it in .env (see .env.example)`);
394	  }
395	  return n;
396	}
397	
398	/** Upper-bound input tokens for a prompt of `chars` characters. */
399	export function estimateInputTokens(chars: number): number {
400	  return Math.ceil(Math.max(0, chars) / ESTIMATE_CHARS_PER_TOKEN);
401	}
402	
403	function usd(n: number): string {
404	  return `$${n.toFixed(4)}`;
405	}
406	
407	/** A model call would take the run past NOTARY_MAX_USD. Thrown before the call is made. */
408	export class UsdCapExceededError extends Error {
409	  readonly cap: number;
410	  readonly spent: number;
411	  readonly estimate: number;
412	  readonly role: string;
413	  constructor(role: string, cap: number, spent: number, estimate: number) {
414	    const agent = (AGENTS as Readonly<Record<string, { name: string } | undefined>>)[role]?.name ?? role;
415	    super(
416	      `USD cap reached: ${MAX_USD_ENV}=${cap} — ${usd(spent)} already spent this run` +
417	        (estimate > 0 ? `, the next ${agent} call could cost up to ~${usd(estimate)}` : `, next ${agent} call not made`) +
418	        ` (raise ${MAX_USD_ENV} in .env to continue)`,
419	    );
420	    this.name = "UsdCapExceededError";
421	    this.cap = cap;
422	    this.spent = spent;
423	    this.estimate = estimate;
424	    this.role = role;
425	  }
426	}
