428	/** True for a UsdCapExceededError, including one re-thrown from a replay cassette (matched by name). */
429	export function isUsdCapExceeded(err: unknown): err is Error {
430	  return err instanceof UsdCapExceededError || (err instanceof Error && err.name === "UsdCapExceededError");
431	}
