433	/**
434	 * The configured cap as stated in a stopReason written from a UsdCapExceededError
435	 * ("… NOTARY_MAX_USD=<n> …"), or null. Lets a bundle-derived view report the cap without a schema change.
436	 */
437	export function usdCapFromStopReason(stopReason: string | undefined): number | null {
438	  if (!stopReason) return null;
439	  const m = /\bUSD cap reached: NOTARY_MAX_USD=(\d+(?:\.\d+)?(?:e[+-]?\d+)?)\b/i.exec(stopReason);
440	  if (!m) return null;
441	  const n = Number(m[1]);
442	  return Number.isFinite(n) && n >= 0 ? n : null;
443	}

